      ["On interrompt la perfusion et l'on garde la voie veineuse.","On vérifie l'identité du patient, l'étiquette du produit et les signes vitaux."],
      [("Clémastine (Tavegyl 2 mg/2 ml)","Forme légère : 2 mg IV lente sur 2 à 3 minutes ou IM chez l'adulte ; contre-indiquée en cas de porphyrie, de grossesse, d'allaitement et avant 1 an ; posologies à vérifier dans l'AIPS (Swissmedic)","Elle bloque les récepteurs H1 et calme prurit et plaques avant la reprise lente.",TAV),
       ("Adrénaline (Adrenalin Sintetica 1 mg/ml ; EpiPen 0,3 mg)","Anaphylaxie : 0,5 mg IM au-delà de 12 ans dans la face antérolatérale de la cuisse, à répéter toutes les 5 minutes si besoin, même en cas de thrombopénie ; posologies à vérifier dans l'AIPS (Swissmedic)","Elle corrige rapidement le choc, le bronchospasme et l'œdème des voies aériennes.",ADR),
       ("Méthylprednisolone (Solu-Medrol)","Second choix dans l'allergie, après l'adrénaline ; posologies à vérifier dans l'AIPS (Swissmedic)","Elle complète le traitement sans remplacer l'adrénaline, dont l'effet est immédiat.",SOL)],
      [("soins infirmiers","On surveille de près les 15 premières minutes de chaque poche et l'on observe directement le patient après une reprise.","On repère tôt une évolution vers une forme grave."),("autre","On garde la poche et la tubulure et l'on prévient le laboratoire et le service de transfusion.","On permet l'enquête et le blocage des produits du même donneur."),("éducation thérapeutique","On explique au patient la réaction et l'inscription au dossier.","On facilite la prévention lors des prochaines transfusions.")],
      [("S Urgences vitales Triage 144 REGA","On reconnaît l'anaphylaxie et l'on injecte l'adrénaline IM sans délai."),("P Qualité Sécurité Gestion de l'erreur","On vérifie l'identité, on déclare à Swissmedic et l'on analyse l'événement."),("F Droit médical suisse","On respecte l'obligation de déclarer de l'OMéd et la conservation des données pendant 30 ans.")],
      (["On arrête définitivement la transfusion.","On injecte l'adrénaline IM.","On donne oxygène et remplissage."],[("d'abord","infirmière","Elle débranche la poche, garde la voie veineuse avec du NaCl 0,9 % et appelle le médecin."),("en même temps","médecin","Il injecte 0,5 mg d'adrénaline IM et la répète après 5 minutes si besoin."),("ensuite","équipe de réanimation","Elle assure les voies aériennes, l'oxygène et le remplissage."),("puis","service de transfusion","Il met les produits en quarantaine et participe à l'enquête.")]),
